python3 - <<'PY'
from openpyxl import load_workbook
wb=load_workbook('/root/data/workbook.xlsx', data_only=False)
data=wb['Data']

TARGET_YEARS={2019,2020,2021,2022,2023}
found=[]
for r in range(1,101):
    for c in range(1,61):
        v=data.cell(r,c).value
        if v in TARGET_YEARS:
            found.append((data.cell(r,c).coordinate,v))

print('Found year labels:', found)

# Also: find any row that looks like header by containing 5 consecutive years
for r in range(1,101):
    row=[data.cell(r,c).value for c in range(1,61)]
    # map col index to value for quick
    for start_c in range(1,56):
        seq=[data.cell(r,c).value for c in range(start_c,start_c+5)]
        if seq==[2019,2020,2021,2022,2023]:
            print('Row with consecutive years:', r, 'start col', start_c, 'coord', data.cell(r,start_c).coordinate)
            break

# print a few top rows A-L
for r in range(15,25):
    vals=[data.cell(r,c).value for c in range(1,13)]
    if any(v not in (None,'') for v in vals):
        print(f"Row {r} A-L:", vals)
